// Extract webhook payload
const item = $input.first().json;
const data = item.body || item;
const hazardClass = (data.hazard_class || 'pothole').toLowerCase();
const baseSeverity = Number(data.severity_score || 4.2);
const weather = (data.weather || 'monsoon').toLowerCase();

let weatherLabel = '🌧️ Monsoon / Heavy Rain';
let weatherMultiplier = 1.35;
let hydroplaneRisk = 88;
let predictedRqi = 34;
let surfaceFriction = 0.35;

if (weather.includes('rain') || weather.includes('monsoon')) {
  weatherLabel = '🌧️ Monsoon / Torrential Rain';
  weatherMultiplier = 1.4;
  hydroplaneRisk = 92;
  predictedRqi = Math.max(15, Math.round(100 - (baseSeverity * 13) - 35));
  surfaceFriction = 0.32;
} else if (weather.includes('heat')) {
  weatherLabel = '☀️ Extreme Heat (>42°C)';
  weatherMultiplier = 1.15;
  hydroplaneRisk = 5;
  predictedRqi = Math.max(25, Math.round(100 - (baseSeverity * 9) - 15));
  surfaceFriction = 0.74;
} else {
  weatherLabel = '☀️ Dry & Clear';
  weatherMultiplier = 1.0;
  hydroplaneRisk = 8;
  predictedRqi = Math.max(40, Math.round(100 - (baseSeverity * 8)));
  surfaceFriction = 0.88;
}

const adjustedSeverity = Math.min(5.0, Number((baseSeverity * weatherMultiplier).toFixed(2)));

return [{
  json: {
    ...data,
    weather_condition: weatherLabel,
    predicted_rqi: predictedRqi,
    surface_friction: surfaceFriction,
    hydroplaning_risk_pct: hydroplaneRisk,
    weather_adjusted_severity: adjustedSeverity,
    road_health_status: predictedRqi < 40 ? 'CRITICAL HAZARD' : (predictedRqi < 65 ? 'DEGRADED' : 'SATISFACTORY'),
    weather_dispatch_advice: weather.includes('rain') ? 'Deploy high-visibility floating strobe beacons and emergency stormwater pumps' : 'Standard hot-pour asphalt compaction unit'
  }
}];
